package com.sih.learningplatform.service;
import com.sih.learningplatform.dto.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class TrainingRecommendationService { private final CompetencyService competencyService; private static final Map<String,CourseInfo> C=Map.of("public financial management",new CourseInfo("Comprehensive Public Financial Management & GFR 2017","https://igotkarmayogi.gov.in/courses/pfm-gfr-2017","8 Hours"),"procurement & gem",new CourseInfo("Government e-Marketplace (GeM) Procurement Guidelines","https://igotkarmayogi.gov.in/courses/gem-procurement-301","5 Hours"),"rti act & governance",new CourseInfo("Right to Information (RTI) Act & Transparent Governance","https://igotkarmayogi.gov.in/courses/rti-governance-101","3 Hours"),"cybersecurity & data privacy",new CourseInfo("Cyber Security Hygiene & DPDP","https://igotkarmayogi.gov.in/courses/cyber-security-dpdp","6 Hours"),"e-office administration",new CourseInfo("e-Office File Management & Workflow","https://igotkarmayogi.gov.in/courses/eoffice-workflow","4 Hours"),"data analytics in governance",new CourseInfo("Data-Driven Decision Making in Public Administration","https://igotkarmayogi.gov.in/courses/data-analytics-governance","10 Hours"),"citizen grievance redressal",new CourseInfo("CPGRAMS & Citizen Grievance Redressal","https://igotkarmayogi.gov.in/courses/cpgrams-citizen-service","4 Hours"),"project management",new CourseInfo("Public Sector Project Monitoring","https://igotkarmayogi.gov.in/courses/project-management-public-sector","12 Hours"));
 public TrainingRecommendationResponse recommendCourses(Long id){var g=competencyService.analyzeGaps(id);var courses=new ArrayList<CourseRecommendation>();for(String s:g.getMissingSkills()){var x=C.get(s.toLowerCase().trim());if(x==null)x=new CourseInfo("Executive Course on "+s,"https://igotkarmayogi.gov.in/courses/"+s.toLowerCase().replaceAll("[^a-z0-9]+","-"),"4 Hours");courses.add(CourseRecommendation.builder().title(x.title).url(x.url).skillTargeted(s).provider("iGOT Karmayogi (DoPT, GoI)").estimatedDuration(x.duration).build());}return TrainingRecommendationResponse.builder().employeeId(g.getEmployeeId()).employeeName(g.getEmployeeName()).designation(g.getDesignation()).missingSkillsCount(g.getMissingSkills().size()).missingSkills(g.getMissingSkills()).recommendedCourses(courses).build();}
 private record CourseInfo(String title,String url,String duration){}
}
